var findInMountainArray = function(target, mountainArr) {
    const n = mountainArr.length();
    let l = 0, r = n - 1;
    while (l < r) {
        const m = Math.floor((l + r) / 2);
        if (mountainArr.get(m) < mountainArr.get(m + 1)) l = m + 1;
        else r = m;
    }
    const peak = l;
    l = 0; r = peak;
    while (l <= r) {
        const m = Math.floor((l + r) / 2);
        const val = mountainArr.get(m);
        if (val === target) return m;
        if (val < target) l = m + 1;
        else r = m - 1;
    }
    l = peak + 1; r = n - 1;
    while (l <= r) {
        const m = Math.floor((l + r) / 2);
        const val = mountainArr.get(m);
        if (val === target) return m;
        if (val > target) l = m + 1;
        else r = m - 1;
    }
    return -1;
};
